package de.igslandstuhl.database.attendance;import static org.junit.jupiter.api.Assertions.*;import java.time.*;import java.util.*;import org.junit.jupiter.api.Test;
class LessonScheduleTest{@Test void configuredCheckpointsMatchSchoolGrid(){LessonSchedule s=new LessonSchedule("08:00,08:50,09:50,10:40,11:40,12:25");assertEquals(List.of("08:00","08:50","09:50","10:40","11:40","12:25"),s.values());assertEquals(Instant.parse("2026-08-24T07:50:00Z"),s.cutoff(LocalDate.parse("2026-08-24"),3,ZoneId.of("Europe/Berlin"),Instant.EPOCH));}@Test void rejectsInvalidLesson(){LessonSchedule s=new LessonSchedule("08:00,08:50,09:50,10:40,11:40,12:25");assertThrows(IllegalArgumentException.class,()->s.cutoff(LocalDate.now(),7,ZoneOffset.UTC,Instant.now()));}}
